message.content:
{
  "claims_to_add": [
    "The article 'The Capital Cities Challenge' states that since European club competition began in the 1955/56 season, only six clubs that have won came from a capital city: Real Madrid, Chelsea, Benfica, Ajax, Red Star Belgrade and Steaua București.",
    "The article gives examples of capital-city clubs that can be used in the challenge, including AS Roma, Lazio, Paris Saint-Germain, Paris FC, Red Star Paris, Hertha Berlin, 1. FC Union Berlin, BFC Dynamo Berlin, Shamrock Rovers, Bohemians, St. Patrick's Athletic, HJK Helsinki, HIFK, Hearts, and Hibernian."
  ],
  "hypothesis_update": {
    "action": "keep",
    "statement": ""
  }
}

